<template>
    <div class="layout-px-spacing">
             <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Projects</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Budgets</span></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Pending Approval</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>


    <div class="d-flex mt-2 mb-2">
            <h5>BUDGETS PENDING APPROVAL</h5>
        <div class="ms-auto">
            <div class="btn-group">
        <Multiselect
        v-model="project"
        :options="projects"
        placeholder="Select Project"
        label="short_name"
        :searchable="true"        
        :append-to-body="true"
        class="me-2"
    />
                <button class="btn btn-secondary me-2" @click="status = 2">Pending</button>
                <button class="btn btn-success me-2"  @click="status = 3">Approved</button>
                <button class="btn btn-danger me-2"  @click="status=4">Rejected</button>
            </div>
        </div>
    </div>


        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table ">


            <div class="row">
                <div  v-for="budget in budgets" class="col-md-4 card ">
  <div class="card-body">
    <h6 class="card-title"><strong>Budget : {{budget.budget_name}}</strong></h6>
    <p class="card-text">Project : {{ budget.project }}</p>
    <p class="card-text">Registered By : {{ budget.issuer }}</p>
    <p class="card-text">IPC Cost : {{ formatRate(budget.total_ipc_cost) }}</p>
    <p class="card-text">Budget Status : 
        <span :class="budget.budget_status === 'open' ? 'badge badge-success' : 'badge badge-dark'">
           {{ budget.budget_status }}
        </span>
    </p>
      <p class="justify-content-right">
        <div class="btn-group ">
        <button class="btn btn-success  me-2"  @click="printBudget(budget)"><i class="bi bi-printer "></i></button>
        <button class="btn btn-secondary me-2"   data-bs-toggle="modal" data-bs-target="#edit" @click="selectedBudget = budget">EDIT IPC</button>
        <button class="btn btn-warning  me-2" v-if="budget.status_name ==='approved'"  @click="changeBudgetStatus(2,budget.budget_approval_id)"  :disabled="sending">
        <span v-if="sending" v-html="loadingSpinner()"></span>
         <span v-else>   Revert</span>
        </button>
        <button class="btn btn-primary " v-else  @click="changeBudgetStatus(3,budget.budget_approval_id)" :disabled="sending">
         <span v-if="sending" v-html="loadingSpinner()"></span>
         <span v-else>   Approve</span>
        </button>
        </div>
    </p>
  </div>
                </div>
                <div class="mx-2" v-if="budgets.length == 0">
                   <div class="alert alert-info w-50" role="alert">
 <i class="bi bi-info fs-5"></i> No Pending Budget Available
</div>
                </div>
            </div>



        </div>
    </div>
   

<!-- ========= update budget modal starts ==-->
                  <div class="modal fade mymodal" id="edit" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">{{ selectedBudget.project }} , {{ selectedBudget.budget_name }} BUDGET  APPROVAL</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-modal" ></button>
      </div>
<div class="modal-body" >
      <div class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
<table class="table">
  <thead>
    <tr>
      <th scope="col">#</th>
      <th scope="col">Description</th>
      <th scope="col">BOQ </th>
      <th scope="col">IPC </th>
      <th scope="col">Unit</th>
      <th scope="col">Rate</th>
      <th scope="col">Total</th>
    </tr>
  </thead>
  <tbody>
    <tr v-for="(line,index) in selectedBudget.boq_lines">
      <th scope="row">{{ index + 1 }}</th>
      <td>{{ line.name }}</td>
      <td>{{ line.quantity.toLocaleString() }}</td>
      <td><input type="number" class="form-control" v-model="line.ipc_quantity" placeholder="Enter Quantity" style="min-width: 220px;"></td>
      <td>{{ formatRate(line.rate) }}</td>
      <td>{{ formatRate(line.quantity * line.rate) }}</td>
    </tr>
  </tbody>
</table>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>
        <button type="button" class="btn btn-primary btn-sm py-2 px-2" @click="submitBudget()" :disabled="loading">
        <span v-if="loading" v-html="loadingSpinner()"></span>
        <span v-else>Submit</span>
        </button>
      </div>


    </div>
  </div>

</div>

 <!-- ======== update budget modal ends ==== -->
</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
     const route = useRoute();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const loadingSpinner = inject('loadingSpinner')

    const formatRate = inject('formatRate')
    const formatNumber = inject('formatNumber')
    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
    const showMessage = inject('showMessage')
 const loading = ref(false);
const budgets = ref([])
const selectedBudget = ref('')
const status = ref(2)
const getBudgets = async() =>{
    loading.value = true
    try{
        let query = `status_id=${status.value}`
        if (project.value && project.value.id) {
            query += `&project_id=${project.value.id}`
        }
        const response = await axiosInstance.get(`budget-approvals?${query}`)
        budgets.value = response.data.map((item,index)=>({
          ...item,
          Sno : index + 1,
        }));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}

const submitBudget = async ()=>{
loading.value = true
    const payload = {
     budget_id : selectedBudget.value.id,
     boq_lines :  selectedBudget.value.boq_lines.map((item)=>({
        id : item.id,
        quantity : item.ipc_quantity
    }))
    }
    try{
        const response = await axiosInstance.put('project-plan-boq-lines',payload)
        showMessage('Budget Approved')
        getBudgets(2)
        document.getElementById('close-modal').click()
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
      loading.value = false
    }
}



const printBudget = async (budget) => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Budget Report</title>
<style>
  body {
    font-family: 'Courier New', monospace;
    margin: 40px;
    font-size: 13px;
  }

  .text-style {
    font-family: 'Courier New', monospace;
  }

  .company-title {
    text-align: center;
  }

  .title {
    text-align: center;
    font-size: 20px;
    margin: 10px 0;
    font-weight: bold;
  }

  .info-table {
    width: 100%;
    margin-top: 10px;
    margin-bottom: 15px;
    border-collapse: collapse;
  }

  .info-table td {
    border: none;
    padding: 3px;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
  }

  th,
  td {
    border: 0.5px solid #000;
    padding: 6px;
  }

  th {
    background: #f8f8f8;
    font-weight: bold;
  }

  .text-right {
    text-align: right;
  }

  .text-center {
    text-align: center;
  }

  hr {
    border: 0;
    border-top: 0.5px solid #000;
    margin: 0;
  }

  @media print {
    body {
      margin: 10mm;
    }
  }
</style>
</head>

<body>

<div class="company-title text-style">
<i>
<h1>COPEX CONTRACTORS CO. LTD</h1>
<div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
<div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
<div><b>Email:</b> info@copexcontractors.co.tz</div>
<div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
</i>
</div>

<hr style="margin-top:20px">

<div class="title">
BUDGET ESTIMATED IPC REPORT
</div>

<hr>

<table class="info-table">
<tr>
<td><b>Project</b></td>
<td>: ${budget.project}</td>

<td><b>Date</b></td>
<td>: ${new Date(budget.date).toLocaleDateString()}</td>
</tr>

<tr>
<td><b>Budget</b></td>
<td>: ${budget.budget_name}</td>

<td><b>Prepared By</b></td>
<td>: ${budget.issuer}</td>
</tr>

${
  budget.budget_description
    ? `
<tr>
<td><b>Description</b></td>
<td colspan="3">: ${budget.budget_description}</td>
</tr>
`
    : ""
}
</table>

<table>
<thead>
<tr>
<th style="width:5%">No.</th>
<th>Description</th>
<th style="width:10%">Unit</th>
<th style="width:12%">Quantity</th>
<th style="width:15%">Rate</th>
<th style="width:18%">Cost</th>
</tr>
</thead>

<tbody>

${budget.boq_lines
  .map(
    (item, index) => `
<tr>
<td class="text-center">${index + 1}</td>
<td>${item.name}</td>
<td class="text-center">${item.unit}</td>
<td class="text-right">${Number(item.ipc_quantity).toLocaleString()}</td>
<td class="text-right">${Number(item.rate).toLocaleString()}</td>
<td class="text-right">${Number(item.ipc_cost).toLocaleString()}</td>
</tr>
`
  )
  .join("")}

<tr>
<td colspan="5" class="text-right">
<strong>TOTAL IPC COST</strong>
</td>
<td class="text-right">
<strong>${Number(budget.total_ipc_cost).toLocaleString()}</strong>
</td>
</tr>

</tbody>
</table>


<hr style="margin-top:30px">

<table style="width:100%; border:none; margin-top:20px;">
    <tr>
        <td style="border:none; width:50%;">
            <strong>Printed By:</strong> ${JSON.parse(localStorage.getItem('user')).name || 'System User'}
        </td>
        <td style="border:none; text-align:right;">
            <strong>Date Printed:</strong> ${new Date().toLocaleString()}
        </td>
    </tr>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();

      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};

const sending = ref(false)
const changeBudgetStatus = async(status,id)=>{
    sending.value = true
    const payload = {
        status_id : status,
        approved_by : JSON.parse(localStorage.getItem("user")).id
    }
    try{
    const response = await axiosInstance.put(`budget-approvals/${id}`,payload)
    showMessage('Budget Approved')
    getBudgets(2)
    }catch(error){
        showError(error.message)
        console.log(error)
    }finally{
      sending.value = false
    }

}

const projects = ref([])
const project = ref('')
const getProjects = async () => {
    try {
        const response = await axiosInstance.get(`projects?company_id=6&status=active`);
        projects.value = response.data   
        .filter(item => item.contracted === 'YES')
        .filter(item => item.status === 'active');
    } catch (error) {
        showError(error.message);
        console.log(error)
      
    }
};

    watch(project, (newVal) => {
      getBudgets()
    });

    watch(status, (newVal) => {
      getBudgets(2)
    });


    onMounted(() => {
      getBudgets(2)
      getProjects()
    });

</script>